#### 1. Environment Variable Presence Validation
At application startup, you should verify that all required environment variables are defined and match the expected format, without actually sending requests to external services.

Here is an example of how to implement a startup configuration check:

```javascript
// config.js
const requiredEnvVars = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY'
];

function validateConfig() {
  const missing = [];

  requiredEnvVars.forEach((key) => {
    if (!process.env[key]) {
      missing.push(key);
    }
  });

  if (missing.length > 0) {
    throw new Error(`Configuration Error: Missing required environment variables: ${missing.join(', ')}`);
  }

  // Optional: Basic format validation (e.g., checking if DATABASE_URL starts with postgres://)
  if (process.env.DATABASE_URL && !process.env.DATABASE_URL.startsWith('postgres://')) {
