      const limitVal = parseInt(limit, 10);
      if (limitVal <= 0 || limitVal > 100) {
        const err = new Error('Invalid query parameter: limit must be between 1 and 100');
        err.status = 400;
        throw err;
      }
    }

    if (page !== undefined) {
      // Ensure page is a valid positive integer
      if (!/^\d+$/.test(page)) {
        const err = new Error('Invalid query parameter: page must be a positive integer');
        err.status = 400;
        throw err;
      }
      const pageVal = parseInt(page, 10);
      if (pageVal <= 0) {
        const err = new Error('Invalid query parameter: page must be greater than 0');
        err.status = 400;
        throw err;
      }
    }

    // If validation passes, return the users (optionally paginated)
    res.json(users);
  } catch (error) {
    next(error);
  }
